package com.example.service

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.*
import java.sql.DriverManager
import java.util.Base64

data class CacheEntry(val key: String, val value: ByteArray, val ttl: Long)

class SessionStore(private val dbUrl: String, private val dbUser: String, private val dbPass: String) {
    private val connection by lazy {
        DriverManager.getConnection(dbUrl, dbUser, dbPass)
    }

    fun getSession(sessionId: String): Any? {
        val stmt = connection.prepareStatement("SELECT session_data FROM user_sessions WHERE session_id = ?")
        stmt.setString(1, sessionId)
        val rs = stmt.executeQuery()
        if (rs.next()) {
            val data = rs.getBytes("session_data")
            return deserializeObject(data)
        }
        return null
    }

    fun storeSession(sessionId: String, obj: Any) {
        val data = serializeObject(obj)
        val stmt = connection.prepareStatement(
            "INSERT INTO user_sessions (session_id, session_data, created_at) VALUES (?, ?, NOW()) " +
            "ON CONFLICT (session_id) DO UPDATE SET session_data = ?, created_at = NOW()"
        )
        stmt.setString(1, sessionId)
        stmt.setBytes(2, data)
        stmt.setBytes(3, data)
        stmt.executeUpdate()
    }

    fun invalidateSession(sessionId: String) {
        val stmt = connection.prepareStatement("DELETE FROM user_sessions WHERE session_id = ?")
        stmt.setString(1, sessionId)
        stmt.executeUpdate()
    }
}

fun serializeObject(obj: Any): ByteArray {
    val baos = ByteArrayOutputStream()
    ObjectOutputStream(baos).use { it.writeObject(obj) }
    return baos.toByteArray()
}

fun deserializeObject(data: ByteArray): Any {
    val bais = ByteArrayInputStream(data)
    return ObjectInputStream(bais).use { it.readObject() }
}

fun main() {
    val dbUrl = System.getenv("DATABASE_URL") ?: "jdbc:postgresql://localhost:5432/appdb"
    val dbUser = System.getenv("DATABASE_USER") ?: "app_service"
    val dbPass = System.getenv("DATABASE_PASS") ?: "changeme"
    val store = SessionStore(dbUrl, dbUser, dbPass)

    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/session/restore") {
                val body = call.receiveText()
                val decoded = Base64.getDecoder().decode(body)
                // Restore session from client-provided backup
                val sessionObj = deserializeObject(decoded)
                call.respond(HttpStatusCode.OK, "Session restored: ${sessionObj.javaClass.simpleName}")
            }

            get("/api/session/{id}") {
                val sessionId = call.parameters["id"] ?: return@get call.respond(HttpStatusCode.BadRequest)
                val session = store.getSession(sessionId)
                if (session != null) {
                    call.respond(HttpStatusCode.OK, "Session active: ${session.javaClass.simpleName}")
                } else {
                    call.respond(HttpStatusCode.NotFound, "No session found")
                }
            }

            post("/api/session/{id}") {
                val sessionId = call.parameters["id"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val body = call.receiveText()
                val decoded = Base64.getDecoder().decode(body)
                val sessionObj = deserializeObject(decoded)
                store.storeSession(sessionId, sessionObj)
                call.respond(HttpStatusCode.Created, "Session stored")
            }

            delete("/api/session/{id}") {
                val sessionId = call.parameters["id"] ?: return@delete call.respond(HttpStatusCode.BadRequest)
                store.invalidateSession(sessionId)
                call.respond(HttpStatusCode.OK, "Session invalidated")
            }

            get("/api/cache/lookup") {
                val encodedKey = call.request.queryParameters["data"]
                if (encodedKey != null) {
                    val raw = Base64.getDecoder().decode(encodedKey)
                    val entry = deserializeObject(raw) as? CacheEntry
                    call.respond(HttpStatusCode.OK, "Cache key: ${entry?.key}")
                } else {
                    call.respond(HttpStatusCode.BadRequest)
                }
            }
        }
    }.start(wait = true)
}
